import json,os
p=os.path.expanduser("~/.claude.json")
try:
    d=json.load(open(p))
except Exception as e:
    print("ERR",e); raise SystemExit
def walk(o,path="",depth=0):
    if depth>4: return
    if isinstance(o,dict):
        for k,v in o.items():
            if "mcp" in k.lower() or "connector" in k.lower():
                print(f"{path}.{k} -> {json.dumps(v)[:600]}")
            else:
                walk(v,f"{path}.{k}",depth+1)
walk(d)
EOF

